# Find the largest number — an algorithm in 4 steps
def largest(nums):
    best = nums[0]
    for n in nums[1:]:
        if n > best:
            best = n
    return best

def factorial(n):
    if n == 0:          # base case
        return 1
    return n * factorial(n - 1)

